let updateState={stage:'idle'},updateHidden=false;
const updateBanner=document.createElement('aside');updateBanner.className='update-banner hidden';updateBanner.setAttribute('role','status');document.body.append(updateBanner);
function paintUpdate(state){updateState=state||updateState;if(focusOpen)focusPanel.append(updateBanner);else document.body.append(updateBanner);const s=updateState,visible=['available','downloading','downloaded','installing'].includes(s.stage)||s.stage==='error'&&!updateHidden;updateBanner.classList.toggle('hidden',!visible||updateHidden);if(!visible)return;updateBanner.innerHTML=`<span class="update-symbol">${playerIcon(s.stage==='downloaded'?'check':'download')}</span><div><strong>${s.version?'soulroom '+esc(s.version):'Обновление soulroom'}</strong><span>${esc(s.message||'')}</span>${s.stage==='downloading'?`<progress max="100" value="${s.percent||0}" aria-label="Загрузка обновления"></progress><small>${Math.round(s.percent||0)}%</small>`:''}</div><div class="update-buttons">${s.stage==='available'?'<button class="primary" data-update-action="download">Загрузить</button>':s.stage==='downloaded'?'<button class="primary" data-update-action="install">Установить и перезапустить</button>':s.stage==='error'?'<button class="secondary" data-update-action="check">Повторить</button>':''}<button data-update-action="hide" aria-label="Скрыть уведомление">×</button></div>`;if($('#updateSettingsState'))$('#updateSettingsState').textContent=s.message||''}
window.playerDesktop?.onUpdateState(s=>{if(s.stage!==updateState.stage||s.version!==updateState.version)updateHidden=false;paintUpdate(s)});
window.playerDesktop?.updateStatus().then(paintUpdate).catch(()=>{});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-update-action]');if(!b)return;const action=b.dataset.updateAction;if(action==='hide'){updateHidden=true;paintUpdate();return}updateHidden=false;b.disabled=true;try{if(action==='install')await window.playerDesktop?.installUpdate();else paintUpdate(await (action==='download'?window.playerDesktop?.downloadUpdate():window.playerDesktop?.checkUpdate()))}catch{paintUpdate({stage:'error',message:'Не удалось проверить обновление. Попробуй снова.'})}finally{b.disabled=false}});
const connectionsBeforeUpdates=connectionsScreen;connectionsScreen=function(){return connectionsBeforeUpdates()+`<section class="settings-card update-settings"><div><h3>Обновления soulroom</h3><p id="updateSettingsState">${esc(window.playerDesktop?updateState.message||'Проверка при запуске и каждые четыре часа':'Автообновление доступно в установленном приложении.')}</p></div><button class="secondary" data-update-action="check" ${!window.playerDesktop?'disabled':''}>Проверить обновления</button></section>`};
const openFocusBeforeUpdates=openFocus;openFocus=function(){openFocusBeforeUpdates();paintUpdate()};const closeFocusBeforeUpdates=closeFocus;closeFocus=function(){closeFocusBeforeUpdates();paintUpdate()};
